from pathlib import Path
import json

root = Path('.')

# package.json: add a stable E2E command. The dependency itself is installed by the workflow
# so package-lock.json is generated by npm rather than edited by hand.
pkg_path = root / 'package.json'
pkg = json.loads(pkg_path.read_text())
pkg.setdefault('scripts', {})['test:e2e'] = 'playwright test'
pkg_path.write_text(json.dumps(pkg, ensure_ascii=False, indent=2) + '\n')

(root / 'playwright.config.ts').write_text('''import { defineConfig, devices } from "@playwright/test";\n\nexport default defineConfig({\n  testDir: "./e2e",\n  fullyParallel: false,\n  retries: process.env.CI ? 1 : 0,\n  reporter: process.env.CI ? [["list"], ["html", { open: "never" }]] : "list",\n  use: {\n    baseURL: "http://127.0.0.1:3100",\n    trace: "retain-on-failure",\n  },\n  webServer: {\n    command: "npm run dev -- --hostname 127.0.0.1 --port 3100",\n    url: "http://127.0.0.1:3100",\n    reuseExistingServer: !process.env.CI,\n    timeout: 120_000,\n  },\n  projects: [\n    {\n      name: "chromium",\n      use: { ...devices["Desktop Chrome"] },\n    },\n  ],\n});\n''')

(root / 'e2e').mkdir(exist_ok=True)
(root / 'e2e' / 'core.spec.ts').write_text('''import { expect, test, type Page } from "@playwright/test";\nimport { readFile } from "node:fs/promises";\n\nconst seedDoc = {\n  title: "E2E demo",\n  paletteKey: "purple",\n  frame: "phone",\n  brief: "",\n  groups: [\n    {\n      id: "home-group",\n      x: 32,\n      y: 120,\n      axis: "x",\n      items: [\n        {\n          id: "go-details",\n          kind: "button",\n          label: "Go details",\n          icon: null,\n          variant: "filled",\n          action: { to: "details", transition: "slide" },\n        },\n      ],\n    },\n    {\n      id: "details-group",\n      x: 564,\n      y: 120,\n      axis: "x",\n      items: [\n        {\n          id: "details-label",\n          kind: "button",\n          label: "Details page",\n          icon: null,\n          variant: "filled",\n        },\n      ],\n    },\n  ],\n  frames: [\n    { id: "home", name: "Home", x: 0, y: 0 },\n    { id: "details", name: "Details", x: 532, y: 0 },\n  ],\n};\n\nasync function openSeeded(page: Page) {\n  await page.addInitScript(({ doc }) => {\n    localStorage.setItem("m3e:doc", JSON.stringify(doc));\n    localStorage.setItem("m3e:ui", JSON.stringify({ lang: "en" }));\n  }, { doc: seedDoc });\n  await page.goto("/");\n  await expect(page.getByTitle("Preview (P)")).toBeVisible();\n}\n\ntest("adds a screen and persists the shared document model", async ({ page }) => {\n  await openSeeded(page);\n\n  await page.getByTitle("Add screen").click();\n\n  await expect.poll(async () =>\n    page.evaluate(() => {\n      const raw = localStorage.getItem("m3e:doc");\n      return raw ? (JSON.parse(raw).frames?.length ?? 0) : 0;\n    }),\n  ).toBe(3);\n});\n\ntest("preview follows a configured screen action", async ({ page }) => {\n  await openSeeded(page);\n\n  await page.getByTitle("Preview (P)").click();\n  const preview = page.getByTestId("preview");\n  await expect(preview).toBeVisible();\n  await expect(preview.getByText("Go details", { exact: true })).toBeVisible();\n\n  await preview.getByText("Go details", { exact: true }).click();\n  await expect(preview.getByText("Details page", { exact: true })).toBeVisible();\n\n  await page.keyboard.press("Escape");\n  await expect(preview).toBeHidden();\n  await expect(page.getByTitle("Preview (P)")).toBeVisible();\n});\n\ntest("exports a versioned project and imports another one", async ({ page }) => {\n  await openSeeded(page);\n\n  await page.getByTitle("Project").click();\n  const downloadPromise = page.waitForEvent("download");\n  await page.getByTitle("Save project").click();\n  const download = await downloadPromise;\n  const downloadPath = await download.path();\n  expect(downloadPath).not.toBeNull();\n  const exported = JSON.parse(await readFile(downloadPath!, "utf8"));\n  expect(exported.format).toBe("web-canvas-project");\n  expect(exported.version).toBe(1);\n  expect(exported.doc.frames).toHaveLength(2);\n\n  const importedDoc = {\n    ...seedDoc,\n    title: "Imported E2E project",\n    groups: [],\n    frames: [{ id: "imported", name: "Imported", x: 0, y: 0 }],\n  };\n  await page.locator('input[type="file"]').setInputFiles({\n    name: "imported.json",\n    mimeType: "application/json",\n    buffer: Buffer.from(JSON.stringify({\n      format: "web-canvas-project",\n      version: 1,\n      doc: importedDoc,\n    })),\n  });\n\n  const dialog = page.getByRole("dialog");\n  await expect(dialog).toContainText("Open this project?");\n  await dialog.getByRole("button").last().click();\n\n  await expect(page.locator('[data-frame="imported"]')).toBeVisible();\n  await expect.poll(async () =>\n    page.evaluate(() => {\n      const raw = localStorage.getItem("m3e:doc");\n      return raw ? JSON.parse(raw).title : null;\n    }),\n  ).toBe("Imported E2E project");\n});\n''')

# Give E2E tests one stable boundary without coupling them to implementation classes.
preview_path = root / 'components' / 'Preview.tsx'
preview = preview_path.read_text()
needle = '  return (\n    <motion.div\n      initial={{ opacity: 0 }}\n'
replacement = '  return (\n    <motion.div\n      data-testid="preview"\n      initial={{ opacity: 0 }}\n'
if needle not in preview:
    raise SystemExit('Preview root marker not found')
preview_path.write_text(preview.replace(needle, replacement, 1))

ci_path = root / '.github' / 'workflows' / 'ci.yml'
ci = ci_path.read_text()
if 'name: e2e' not in ci:
    ci = ci.rstrip() + '''\n\n  e2e:\n    name: e2e\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npx playwright install --with-deps chromium\n      - run: npm run test:e2e\n''' + '\n'
ci_path.write_text(ci)
